args.TargetContent:
"        function getWorkflowProgress(asset, mode) {
            try {
                const data = JSON.parse(localStorage.getItem('rivenquant_workflow_progress') || '{}');
                if (!data[asset]) data[asset] = { ai: 0, custom: 0 };

                // Auto-detect step on first load if state is uninitialized
                if (data[asset][mode] === undefined || data[asset][mode] === 0) {
                    const pnlVal = document.getElementById('stat-pnl')?.innerText || '—';
                    const isSignaler = document.getElementById('signaler-badge-text')?.innerText === 'live_node';

                    if (isSignaler) {
                        data[asset][mode] = mode === 'ai' ? 7 : 5;
                    } else if (pnlVal !== '—') {
                        data[asset][mode] = mode === 'ai' ? 6 : 4;
                    } else {
                        data[asset][mode] = 0;
                    }
                    localStorage.setItem('rivenquant_workflow_progress', JSON.stringify(data));
                }

                return data[asset][mode];
            } catch (e) {
                return 0;
            }
        }"
